'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={user:null,csrf:'',token:localStorage.getItem('fitadapt_token')||'',onboarded:false,chart:null,timer:null,range:'month',exerciseId:'',onboarding:{goal:'build_muscle',level:'beginner',equipment_level:'full_gym',limitation_notes:'',session_minutes:45,days:[1,3,5]},step:1};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M8 2v4 M16 2v4 M3 9h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M7 13h3 M14 13h3 M7 17h3',log:'M7 3h10v18H4V3h3 M8 7h5 M8 11h5 M8 15h5 M17 5h3v16h-3',chart:'M3 3v18h18 M6 15l4-5 4 3 6-8',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',arrow:'M4 12h16 M14 6l6 6-6 6',back:'M20 12H4 M10 6l-6 6 6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',dumbbell:'m6 6 12 12 M3 7l4-4 M2 10l8-8 M14 22l8-8 M17 21l4-4 M5 12l7-7 M12 19l7-7',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',leaf:'M20 3C7 2 2 8 5 15s15 2 15-12 M4 21 16 8',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M9 4H3v16h6 M10 12h11 M17 8l4 4-4 4',message:'M21 3H3v14h5v4l5-4h8z M7 7h10 M7 11h7',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3 M17 3a4 4 0 0 1 0 8 M18 14a5 5 0 0 1 4 5v2',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z m-4 10 3 3 5-6',plus:'M12 4v16 M4 12h16',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',flame:'M13 2c0 6 7 8 7 14a8 8 0 0 1-16 0c0-4 2-7 5-9 0 4 3 5 3 5s3-5 1-10',edit:'m15 4 5 5 M4 20l5-1L21 7l-5-5L4 14z'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.dumbbell}"/></svg>`;}
const brand=(mobile=false)=>`<a class="brand ${mobile?'mobile-brand':''}" href="#${state.user?'dashboard':'home'}"><img src="/img/logo.svg" alt=""><span>Fit<em>Adapt</em></span></a>`;
const labels={build_muscle:'Bina otot',lose_weight:'Kurus',general_fitness:'Kecergasan am',beginner:'Pemula',intermediate:'Sederhana',advanced:'Lanjutan',none:'Tiada peralatan',dumbbell:'Dumbbell',full_gym:'Gim penuh',bodyweight:'Berat badan',barbell:'Barbell',machine:'Mesin',cable:'Kabel',chest:'Dada',back:'Belakang',legs:'Kaki',shoulders:'Bahu',arms:'Lengan',core:'Teras',push:'Tolak',pull:'Tarik',squat:'Squat',hinge:'Hinge',scheduled:'Belum dimulakan',in_progress:'Sedang berjalan',completed:'Siap',partial:'Separa',missed:'Terlepas',rescheduled:'Dijadualkan semula',active:'Aktif',suspended:'Digantung',user:'Pengguna',admin:'Pentadbir',coach:'Jurulatih'};
const days=['Isn','Sel','Rab','Kha','Jum','Sab','Ahd'];
const localToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const fmt=(date,options={day:'numeric',month:'long',year:'numeric'})=>date?new Intl.DateTimeFormat('ms-MY',{timeZone:'Asia/Kuala_Lumpur',...options}).format(new Date(date.length===10?date+'T00:00:00+08:00':date.replace(' ','T')+'Z')):'—';
const badge=status=>`<span class="badge ${['completed','active'].includes(status)?'green':['missed','suspended'].includes(status)?'red':status==='partial'?'amber':''}">${esc(labels[status]||status)}</span>`;
const button=(text,href,cls='')=>`<a class="button ${cls}" href="#${href}">${text}</a>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,credentials:'include',headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...(state.token?{'Authorization':'Bearer '+state.token}:{})},...(data?{body:JSON.stringify(data)}:{})});const body=await r.json();if(!r.ok){const error=new Error(body.error?.message||'Permintaan gagal.');error.status=r.status;error.fields=body.error?.fields;throw error;}return body;}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function select(label,name,values,value,extra=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${values.map(v=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(labels[v]||v)}</option>`).join('')}</select></div>`;}
function formData(form){return Object.fromEntries(new FormData(form));}
function bindForm(selector,handler){const form=$(selector);form.addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;if(b)b.disabled=true;const error=form.querySelector('.form-error');if(error)error.innerHTML='';try{await handler(formData(form),form);}catch(e){if(error)error.innerHTML=`<div class="alert error" role="alert">${esc(e.message)}${e.fields?.length?'<br>'+e.fields.map(f=>esc(f.message)).join('<br>'):''}</div>`;else toast(e.message);}finally{if(b)b.disabled=false;}});}
const workoutStatus=(exercise,finished)=>finished?badge(exercise.status):'<span class="badge" id="exercise-save-status">'+exercise.sets.length+' / '+exercise.target_sets+' set disimpan</span>';
const empty=(title,text,ico='calendar')=>`<div class="empty">${icon(ico)}<h3>${title}</h3><p>${text}</p></div>`;
function modal(title,content){const d=$('#modal');d.innerHTML=`<button class="icon-button close" data-close aria-label="Tutup">${icon('close')}</button><h2 id="modal-title">${title}</h2><div class="modal-content">${content}</div>`;d.querySelector('[data-close]').onclick=()=>d.close();if(!d.open)d.showModal();}
function confirmAction(title,text,onConfirm){modal(title,`<p>${text}</p><div class="form-actions"><button class="button secondary" id="cancel-action">Batal</button><button class="button danger" id="confirm-action">Sahkan</button></div>`);$('#cancel-action').onclick=()=>$('#modal').close();$('#confirm-action').onclick=async()=>{try{$('#confirm-action').disabled=true;await onConfirm();$('#modal').close();}catch(e){toast(e.message);$('#confirm-action').disabled=false;}};}
function pageHeading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
const navItems=[['dashboard','grid','Hari ini'],['plan','calendar','Planner'],['progress','chart','Kemajuan'],['profile','user','Akaun']];
const adminItems=[['admin','grid','Dashboard'],['admin-exercises','dumbbell','Urus senaman'],['admin-users','users','Urus akaun'],['admin-feedback','message','Maklum balas']];
function shell(content,active='dashboard'){
 const admin=state.user.role==='admin',items=admin?adminItems:navItems;const initials=state.user.full_name.split(' ').slice(0,2).map(s=>s[0]).join('');const nav=items.map(([url,ico,title])=>`<a href="#${url}" class="${active===url?'active':''}" ${active===url?'aria-current="page"':''}>${icon(ico)}<span>${title}</span></a>`).join('');
 $('#app').innerHTML=`<aside class="sidebar ${admin?'admin':''}">${brand()}<div class="nav-label">${admin?'RUANG PENTADBIR':'RUANG LATIHAN'}</div><nav class="nav" aria-label="Navigasi utama">${nav}</nav><div class="sidebar-bottom">${admin?'':`<div class="sidebar-tip"><h3>Baru bermula?</h3><p>Ikuti panduan ringkas, bila-bila masa.</p><button class="button secondary compact" id="open-help">Cara guna FitAdapt</button></div>`}<nav class="nav"><a href="#${admin?'admin-profile':'feedback'}">${icon(admin?'user':'message')}<span>${admin?'Profil pentadbir':'Maklum balas'}</span></a><a href="#logout">${icon('logout')}<span>Log keluar</span></a></nav><div class="user-mini row"><div class="avatar">${esc(initials)}</div><div><strong class="small">${esc(state.user.full_name.split(' ')[0])}</strong><div class="small muted">${admin?'Pentadbir':'Ahli FitAdapt'}</div></div></div></div></aside><div class="app-frame"><header class="topbar">${brand(true)}<div class="breadcrumb">${admin?'FitAdapt Admin':'Ruang latihan'} <b>/ &nbsp; ${items.find(i=>i[0]===active)?.[2]||'Tetapan'}</b></div><div class="topbar-right"><span class="date-label">${fmt(localToday(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span>${admin?'<span class="badge">Akses: Admin</span>':`<button class="icon-button" id="notifications" aria-label="Notifikasi">${icon('bell')}<span class="dot" id="notification-dot" hidden></span></button>`}<div class="avatar">${esc(initials)}</div></div></header><main id="main" class="content">${content}</main></div><nav class="bottom-nav" aria-label="Navigasi telefon">${(admin?adminItems:navItems).map(([url,ico,title])=>`<a href="#${url}" class="${active===url?'active':''}">${icon(ico)}<span>${title.replace(' latihan','').replace(' & tetapan','')}</span></a>`).join('')}</nav>`;
 if($('#notifications'))$('#notifications').onclick=showNotifications;
 if($('#open-help'))$('#open-help').onclick=()=>modal('Cara guna FitAdapt',beginnerGuide());
 const help=document.createElement('button');help.className='button secondary compact';help.textContent='Bantuan';help.onclick=()=>modal('Cara guna FitAdapt',beginnerGuide());$('.topbar-right').prepend(help);
 const avatar=$('.topbar-right .avatar');if(avatar){const link=document.createElement('a');link.className='avatar';link.href='#'+(admin?'admin-profile':'profile');link.setAttribute('aria-label',admin?'Profil pentadbir':'Profil dan tetapan');link.textContent=initials;avatar.replaceWith(link);}
 if(location.hash==='#admin-profile')$('#main').insertAdjacentHTML('beforeend','<div class="narrow" style="margin-top:20px"><a href="#logout" class="button danger">'+icon('logout')+' Log keluar</a></div>');
}
async function showNotifications(){const {notifications}=await api('/notifications');modal('Notifikasi',notifications.length?notifications.map(n=>`<div class="list-item"><div class="row between"><span class="badge ${n.is_read?'gray':''}">${n.is_read?'Dibaca':'Baharu'}</span><small>${fmt(n.created_at)}</small></div><p>${esc(n.message)}</p>${n.is_read?'':`<button class="button ghost compact" data-read="${n.id}">Tandakan dibaca</button>`}</div>`).join(''):empty('Semua sudah dikemas kini','Notifikasi pelan akan muncul di sini.','bell'));$$('[data-read]').forEach(b=>b.onclick=async()=>{await api('/notifications/'+b.dataset.read+'/read','PUT',{});showNotifications();});}
function landing(){
 $('#app').innerHTML=`<div class="landing"><header class="public-header">${brand()}<nav class="links"><a href="#how">Cara ia berfungsi</a><a href="#login">Log masuk</a>${button('Mula percuma '+icon('arrow'),'register','orange compact')}</nav></header><main id="main"><section class="hero"><div><span class="eyebrow">LATIHAN MUDAH UNTUK PEMULA</span><h1>Latih dengan arah.<br><em>Maju dengan yakin.</em></h1><p>Pilih matlamat dan masa yang kamu ada. FitAdapt susun senaman, tunjukkan langkah seterusnya, dan simpan kemajuan kamu.</p><div class="hero-actions">${button('Daftar & mula '+icon('arrow'),'register','orange')}${button('Log masuk','login','secondary')}</div><span class="hero-note">Direka untuk pelajar & pemula · Mudah bermula, mudah konsisten</span></div><div class="hero-preview" aria-label="Contoh paparan sesi latihan"><div class="row between"><div><span class="eyebrow">CONTOH PELAN KAMU</span><h2 style="margin:7px 0 0">Satu sesi, satu langkah.</h2></div>${icon('spark')}</div><div class="card"><div class="row between"><h3>Seluruh Badan</h3><span class="badge green">Sedia berlatih</span></div>${[['Goblet Squat','3 set × 8–12 rep'],['Dumbbell Bench Press','3 set × 8–12 rep'],['Dumbbell Row','3 set × 8–12 rep']].map(([name,detail])=>`<div class="exercise-row"><div class="exercise-art">${icon('dumbbell')}</div><div class="exercise-info"><strong>${name}</strong><span>${detail}</span></div>${icon('check')}</div>`).join('')}<div class="alert success small" style="margin-top:14px">${icon('spark')} Pelan berubah seiring kemajuan kamu.</div></div><p class="preview-label" style="margin:19px 0 0"><i></i> Pelan automatik. Kemajuan yang bermakna.</p></div></section><section class="landing-features"><div><span class="eyebrow">LATIH DENGAN LEBIH YAKIN</span><h2>Fokus pada latihan. Kami urus pelan.</h2><div class="grid3">${[['calendar','Pelan automatik','Disusun mengikut matlamat, masa, peralatan dan tahap kamu.'],['log','Log yang mudah','Rekod rep, beban dan tahap usaha. Semua kemajuan di satu tempat.'],['spark','Pelarasan adaptif','Sasaran latihan berkembang mengikut prestasi dan konsistensi kamu.']].map(([i,t,p])=>`<article class="card"><span class="stat-icon">${icon(i)}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div><div class="steps-section" id="how"><h2>3 langkah mudah untuk mula.</h2><div class="grid3">${[['01','Kenalkan diri kamu','Daftar dan beritahu kami matlamat latihan kamu.'],['02','Dapatkan pelan','Pilih hari dan peralatan. Pelan kamu sedia dalam beberapa langkah.'],['03','Latih & maju','Ikut panduan, simpan log dan lihat kemajuan kamu.']].map(([n,t,p])=>`<div><span class="feature-no">LANGKAH ${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section></main><footer class="public-footer"><span>© ${new Date().getFullYear()} FitAdapt</span><a href="#terms">Terma penggunaan</a><a href="#privacy">Dasar privasi</a></footer></div>`;
}
let authModule;
async function authPage(register){
 const version=renderVersion;
 if(!document.querySelector('link[data-auth-style]')){const link=document.createElement('link');link.rel='stylesheet';link.href='/css/auth.css';link.dataset.authStyle='true';document.head.append(link);}
 $('#app').innerHTML='<main id="main" class="loading">Memuatkan…</main>';
 authModule ||=await import('/js/auth.js');
 if(version!==renderVersion)return;
 authModule.mountAuth($('#app'),{register,initialEmail:register?'':state.registrationEmail||'',successMessage:!register&&state.registrationEmail?'Akaun berjaya didaftarkan. Sila log masuk untuk meneruskan.':'',onSubmit:async data=>{
 const result=await api('/auth/'+(register?'register':'login'),'POST',data);
 if(register){state.registrationEmail=data.email;go('login');return;}
 if(result.token){state.token=result.token;localStorage.setItem('fitadapt_token',result.token);}
 state.registrationEmail='';Object.assign(state,result);
 if(!result.onboarded){state.step=1;state.onboarding={goal:'build_muscle',level:'beginner',equipment_level:'full_gym',limitation_notes:'',session_minutes:45,days:[1,3,5]};}
 go(result.user.role==='admin'?'admin':result.onboarded?'dashboard':'onboarding');
 }});
}

function dayFields(selected){return `<fieldset class="field full"><legend>Hari tersedia <span class="muted">· Pilih 2 hingga 6 hari</span></legend><div class="day-options">${days.map((d,i)=>`<label class="day-option"><input type="checkbox" name="days" value="${i+1}" ${selected.includes(i+1)?'checked':''}><span>${d}</span></label>`).join('')}</div><small id="day-count">Dipilih: ${selected.length} hari</small></fieldset>`;}
function profileFields(p){return `${select('Matlamat latihan','goal',['build_muscle','lose_weight','general_fitness'],p.goal)}${select('Tahap pengalaman','level',['beginner','intermediate'],p.level)}${dayFields(p.days)}${select('Akses peralatan','equipment_level',['none','dumbbell','full_gym'],p.equipment_level)}${field('Tempoh sesi (minit)','session_minutes',p.session_minutes,'number','required min="15" max="120" step="1" aria-describedby="duration-help"')+'<p class="small muted" id="duration-help">Pilih 15–120 minit, contohnya 25 atau 50. Ini anggaran masa latihan kamu.</p>'}<div class="field full"><label for="limitation_notes">Limitasi atau bahagian badan yang perlu dijaga</label><textarea id="limitation_notes" name="limitation_notes" maxlength="200" placeholder="Contoh: sakit lutut, bahu atau belakang">${esc(p.limitation_notes)}</textarea><small>Maksimum 200 aksara. Senaman berkaitan akan dikecualikan.</small></div>`;}
function bindDays(){const update=()=>{const n=$$('input[name=days]:checked').length;$('#day-count').textContent=`Dipilih: ${n} hari`;const b=$('#profile-submit');if(b)b.disabled=n<2||n>6;};$$('input[name=days]').forEach(e=>e.onchange=update);update();}
function parseProfile(data,form){return {...data,days:[...form.querySelectorAll('input[name=days]:checked')].map(e=>Number(e.value)),session_minutes:Number(data.session_minutes)};}
function beginnerGuide(){return '<section class="card beginner-guide"><span class="eyebrow">PANDUAN RINGKAS</span><h2>Mula dengan satu sesi.</h2><ol><li><strong>Lihat apa yang perlu dibuat</strong><p>Buka Jadual untuk melihat hari latihan. Pada hari latihan, tekan Mula latihan di Hari ini.</p></li><li><strong>Ikuti arahan senaman</strong><p>Baca arahan, lakukan senaman dan tandakan setiap set yang selesai.</p></li><li><strong>Simpan dan lihat kemajuan</strong><p>Tandakan Siap selepas setiap set. Tekan Tamat sesi apabila selesai. Rekod kamu ada di Kemajuan → Lihat semua rekod latihan.</p></li></ol><details><summary>Apa maksud set, rep dan RPE?</summary><p><strong>Rep</strong> ialah satu ulangan pergerakan. <strong>Set</strong> ialah sekumpulan ulangan: 3 set × 8 rep bermakna 8 ulangan, rehat, dan ulang sehingga 3 set. <strong>RPE</strong> ialah tahap usaha 1–10; nombor lebih tinggi bermakna lebih mencabar.</p></details></section>';}
const splitLabels={full_body:'Seluruh badan',upper_lower:'Atas & bawah badan',hybrid5:'Gabungan 5 hari',ppl6:'Tolak, tarik & kaki'};
function choiceGroup(title,name,items,value){return '<fieldset class="choice-group" data-choice="'+name+'"><legend>'+title+'</legend><div class="choice-grid">'+items.map(([v,label,desc,ico])=>'<label class="choice-card"><input type="radio" name="'+name+'" value="'+v+'" '+(v===value?'checked':'')+' required><span>'+icon(ico)+'<strong>'+label+'</strong><small>'+desc+'</small><i>'+icon('check')+'</i></span></label>').join('')+'</div></fieldset>';}
function planReason(p,split){return '<div class="reason-grid">'+[['calendar',p.days.length+' hari seminggu',splitLabels[split]||'Jadual mengikut hari pilihan kamu'],['clock',p.session_minutes+' minit / sesi','Masa kamu menentukan jumlah senaman.'],['dumbbell',labels[p.equipment_level],'Senaman ditapis mengikut peralatan & pengalaman.']].map(([i,t,d])=>'<div>'+icon(i)+'<strong>'+t+'</strong><p>'+d+'</p></div>').join('')+'</div>';}
function onboarding(){
 const p=state.onboarding;p.plan_start_date ||=localToday();
 shell(pageHeading('Studio pelan kamu','Dibina daripada pilihan kamu. Berkembang bersama kemajuan kamu.')+'<div class="studio-placeholder"><div class="orbit-art">'+icon('dumbbell')+'</div><h2>Rutin yang terasa milik kamu.</h2><p>Matlamat. Masa. Peralatan. Satu pelan yang menyatukannya.</p></div>');
 let d=$('#setup-dialog');if(!d){d=document.createElement('dialog');d.id='setup-dialog';d.setAttribute('aria-labelledby','setup-title');document.body.append(d);}
 const titles=['Bina latihan mengikut diri kamu.','Beri ruang untuk kemajuan.','Ini cara pelan kamu dibina.','Pelan kamu sudah sedia!'];let body='';
 if(state.step===1)body=choiceGroup('01 / Matlamat kamu','goal',[['build_muscle','Bina otot','Fokus pada kekuatan & bentuk badan.','dumbbell'],['lose_weight','Kawal berat','Bina rutin bergerak yang konsisten.','flame'],['general_fitness','Lebih cergas','Kekal aktif dalam kehidupan harian.','leaf']],p.goal)+choiceGroup('02 / Pengalaman latihan','level',[['beginner','Baru bermula','Saya perlukan panduan langkah demi langkah.','spark'],['intermediate','Sudah biasa','Saya mempunyai pengalaman latihan.','chart']],p.level)+choiceGroup('03 / Tempat & peralatan','equipment_level',[['none','Di rumah','Guna berat badan, tanpa peralatan.','user'],['dumbbell','Dengan dumbbell','Berat badan dan dumbbell.','dumbbell'],['full_gym','Di gim','Akses mesin, barbell & dumbbell.','grid']],p.equipment_level)+'<details class="setup-optional"><summary>Bahagian badan yang perlu dijaga (pilihan)</summary>'+field('Beritahu kami','limitation_notes',p.limitation_notes,'text','maxlength="200" placeholder="Contoh: lutut atau bahu"')+'<p class="small muted">Senaman dengan tag berkaitan akan dikecualikan.</p></details>';
 else if(state.step===2)body='<div class="schedule-builder"><section><h3>Hari apa yang sesuai?</h3><p class="muted">Pilih 2–6 hari. Kami susun latihan dan pemulihan di antaranya.</p>'+dayFields(p.days)+'<div class="duration-presets"><span>Masa untuk diri sendiri</span>'+[20,30,45,60].map(n=>'<button type="button" class="button secondary compact" data-duration="'+n+'">'+n+' min</button>').join('')+'</div><div class="form-grid">'+field('Berapa minit untuk satu latihan?','session_minutes',p.session_minutes,'number','required min="15" max="120" step="1"')+field('Tarikh mula','plan_start_date',p.plan_start_date,'date','min="'+localToday()+'" required')+'</div></section><aside class="setup-insight"><span class="eyebrow">RENTak KAMU</span><strong id="schedule-minutes">'+p.session_minutes+'</strong><span>minit setiap sesi</span><p>Tempoh ialah anggaran. Kamu boleh pilih apa-apa nilai antara 15–120 minit.</p><div id="schedule-week"></div></aside></div>';
 else if(state.step===3){const preview=state.planPreview;body='<p>Kami menggunakan pilihan kamu untuk menghasilkan cadangan sebenar di bawah. Pelan belum disimpan.</p>'+planReason(p,preview.split_type)+'<div class="preview-list">'+preview.sessions.filter(x=>!x.is_rest).slice(0,p.days.length).map(x=>'<article><div><span class="eyebrow">'+fmt(x.scheduled_date,{weekday:'long',day:'numeric',month:'short'})+'</span><h3>'+esc(x.session_label)+'</h3></div><div><strong>'+x.exercises.length+' senaman</strong><p>'+x.exercises.map(e=>esc(e.name)).join(' · ')+'</p></div></article>').join('')+'</div><p class="small muted">Pemilihan senaman berdasarkan pengalaman, peralatan, masa dan pemulihan otot. Sasaran akan dilaraskan mengikut rekod latihan kamu.</p>';}
 else body='<div class="setup-complete">'+icon('check')+'<h3>Langkah pertama, selesai.</h3><p>'+p.days.length+' hari latihan seminggu · '+p.session_minutes+' minit setiap sesi</p><button type="button" class="button" id="finish-setup">Pergi ke latihan saya '+icon('arrow')+'</button></div>';
 d.innerHTML='<div class="setup-heading"><span class="eyebrow">FITADAPT / PLAN STUDIO</span><span>0'+state.step+' / 04</span></div><div class="setup-steps">'+['Diri kamu','Rentak kamu','Pratonton','Sedia'].map((t,i)=>'<span class="'+(i+1<=state.step?'active':'')+'">'+t+'</span>').join('')+'</div><h2 id="setup-title" tabindex="-1">'+titles[state.step-1]+'</h2><p id="setup-required" class="small muted">Pilihan kamu boleh diubah kemudian dalam Akaun.</p><form id="onboarding-form"><div class="form-error"></div>'+body+(state.step<4?'<div class="form-actions">'+(state.step>1?'<button class="button secondary" type="button" id="step-back">Kembali</button>':'')+'<button class="button" id="profile-submit" type="submit">'+(state.step===3?'Jana pelan saya':state.step===2?'Pratonton pelan':'Seterusnya')+icon('arrow')+'</button></div>':'')+'</form><button type="button" class="button ghost compact" id="setup-logout">Log keluar</button>';
 d.oncancel=e=>{e.preventDefault();$('#setup-required').textContent='Selesaikan persediaan atau pilih Log keluar untuk keluar dengan selamat.';};if(!d.open)d.showModal();$('#setup-title').focus();d.scrollTop=0;
 $('#setup-logout').onclick=()=>{d.close();go('logout');};
 if(state.step===2){bindDays();const update=()=>{$('#schedule-minutes').textContent=$('#session_minutes').value||'—';$('#schedule-week').textContent=$$('input[name=days]:checked').length+' hari latihan / minggu';};$('#session_minutes').addEventListener('input',update);$$('input[name=days]').forEach(e=>e.addEventListener('change',update));$$('[data-duration]').forEach(b=>b.onclick=()=>{$('#session_minutes').value=b.dataset.duration;update();});update();}
 if($('#step-back'))$('#step-back').onclick=()=>{if(state.step===2)Object.assign(p,parseProfile(formData($('#onboarding-form')),$('#onboarding-form')));state.step--;onboarding();};
 if($('#finish-setup'))$('#finish-setup').onclick=()=>{d.close();go('dashboard');};
 bindForm('#onboarding-form',async(data,form)=>{if(state.step===1)Object.assign(p,data);if(state.step===2){Object.assign(p,parseProfile(data,form));state.planPreview=await api('/plan/preview','POST',p);}if(state.step===3){await api('/onboarding/complete','POST',p);state.onboarded=true;}state.step++;onboarding();});
}

function exerciseRows(exercises){return exercises.map(e=>`<div class="exercise-row"><div class="exercise-art">${icon('dumbbell')}</div><div class="exercise-info"><strong>${esc(e.name)}</strong><span>${esc(labels[e.muscle_group])} <span aria-hidden="true">·</span> ${e.target_sets} set × ${e.target_rep_min}–${e.target_rep_max} rep</span></div><span class="small muted">${e.target_weight_kg===null?'Beban ringan':e.target_weight_kg+' kg'}</span><button class="exercise-detail" data-exercise="${e.exercise_id}" aria-label="Butiran ${esc(e.name)}">${icon('chevron')}</button></div>`).join('');}
function bindExercises(){$$('[data-exercise]').forEach(b=>b.onclick=async()=>{try{const {exercise:e,alternatives}=await api('/exercises/'+b.dataset.exercise+'/alternatives');modal(esc(e.name),`${e.image_url?`<img src="${esc(e.image_url)}" alt="Demonstrasi ${esc(e.name)}" style="width:100%;max-height:260px;object-fit:contain">`:''}<div class="row wrap"><span class="badge">${labels[e.muscle_group]}</span><span class="badge gray">${labels[e.equipment_type]}</span><span class="badge gray">${labels[e.level]}</span></div><p style="margin-top:20px">${esc(e.instructions)}</p><h3>Senaman alternatif</h3>${alternatives.length?alternatives.map(a=>`<div class="list-item"><strong class="small">${esc(a.name)}</strong><p>${esc(a.instructions)}</p></div>`).join(''):'<p class="muted small">Tiada alternatif sepadan dengan peralatan, tahap dan limitasi kamu.</p>'}`);}catch(e){toast(e.message);}});}
async function dashboard(){
 const [d,{profile:p},{sessions}]=await Promise.all([api('/dashboard'),api('/profile'),api('/plan')]);const s=d.todaySession,training=s&&!s.is_rest,canStart=training&&['scheduled','rescheduled','in_progress'].includes(s.status),done=training&&['completed','partial'].includes(s.status);const weekDate=new Date(d.today+'T00:00:00Z');weekDate.setUTCDate(weekDate.getUTCDate()-((weekDate.getUTCDay()||7)-1));const week=Array.from({length:7},(_,i)=>{const date=new Date(weekDate);date.setUTCDate(date.getUTCDate()+i);return date.toISOString().slice(0,10);});
 shell(pageHeading('Ruang untuk jadi lebih kuat.','Selamat kembali, '+esc(state.user.full_name.split(' ')[0])+'. Ini rentak latihan kamu.',button('Buka planner '+icon('arrow'),'plan','secondary'))+
 '<div class="dashboard-studio"><section class="training-feature"><div class="feature-copy"><span class="eyebrow">'+(done?'LATIHAN DISIMPAN':training?'SESI HARI INI':'RECOVERY DAY')+'</span><h2>'+(done?'Satu langkah lagi<br>untuk diri kamu.':training?esc(s.session_label):'Rehat hari ini.<br>Kembali bertenaga.')+'</h2><p>'+(training?'Pelan sudah tersedia. Fokus pada satu senaman, satu set, satu kemajuan.':'Pemulihan juga sebahagian daripada pelan. Semak sesi seterusnya dan kembali mengikut rentak kamu.')+'</p><div class="feature-tags"><span>'+icon('clock')+' '+p.session_minutes+' minit</span><span>'+icon('dumbbell')+' '+(training?s.exercises.length+' senaman':labels[p.goal])+'</span></div>'+(canStart?'<button class="button" data-start="'+s.id+'">'+(s.status==='in_progress'?'Sambung latihan':'Mula latihan')+' '+icon('arrow')+'</button>':button(done?'Lihat rekod latihan':'Lihat jadual saya',done?'logs':'plan'))+'</div><div class="orbit-art" aria-hidden="true"><span>FIT</span>'+icon(done?'check':'dumbbell')+'<small>YOUR NEXT CHAPTER</small></div></section><section class="card weekly-card"><div class="card-title"><span class="eyebrow">MOMENTUM MINGGU INI</span>'+icon('chart')+'</div><div class="momentum-ring" style="--progress:'+Math.min(100,d.week.percent)+'%" role="img" aria-label="'+d.week.completed+' daripada '+d.week.planned+' sesi selesai"><div><strong>'+d.week.completed+'<small> / '+d.week.planned+'</small></strong><span>latihan selesai</span></div></div><p>'+(d.week.completed?'Kemajuan kamu sedang terbina. Teruskan mengikut kemampuan.':'Satu sesi ialah permulaan yang baik. Sedia bila kamu sedia.')+'</p><a class="section-link" href="#progress">Terokai kemajuan '+icon('arrow')+'</a></section></div>'+
 '<section class="card calendar-overview"><div class="card-title"><div><span class="eyebrow">7 HARI, RENTAK KAMU</span><h2>Minggu ini</h2></div><a href="#plan">Lihat planner '+icon('arrow')+'</a></div><div class="calendar-week">'+week.map((date,i)=>{const session=sessions.find(x=>x.scheduled_date===date);return '<a href="#plan/'+date+'" class="calendar-tile '+(date===d.today?'is-today ':'')+(session&&!session.is_rest?'is-training':'')+'"><span>'+days[i]+'</span><strong>'+Number(date.slice(-2))+'</strong><small>'+(!session?'Belum dijadual':session.is_rest?'Rehat':session.status==='completed'?'Selesai':'Latihan')+'</small></a>';}).join('')+'</div></section>'+
 '<div class="studio-lower"><section class="card"><div class="card-title"><div><span class="eyebrow">'+(training?'DALAM SESI KAMU':'SETERUSNYA')+'</span><h2>'+(training?'Senaman hari ini':'Latihan akan datang')+'</h2></div>'+icon('dumbbell')+'</div>'+(training?exerciseRows(s.exercises):d.nextSession?'<h3>'+esc(d.nextSession.session_label)+'</h3><p>'+fmt(d.nextSession.scheduled_date)+'</p>'+exerciseRows(d.nextSession.exercises.slice(0,3)):empty('Ruang untuk pelan baharu','Buka planner untuk melihat jadual.'))+'</section><section class="card plan-identity"><span class="eyebrow">DIREKA UNTUK KAMU</span><h2>'+labels[p.goal]+'</h2><p>Profil latihan membentuk rutin kamu.</p><dl class="identity-list">'+[['Pengalaman',labels[p.level]],['Peralatan',labels[p.equipment_level]],['Rentak',p.days.length+' hari / minggu'],['Tempoh',p.session_minutes+' minit / sesi']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><a href="#profile" class="button secondary">Ubah pilihan latihan '+icon('edit')+'</a></section></div><details class="card guide-disclosure"><summary>Panduan latihan & istilah yang perlu kamu tahu</summary>'+beginnerGuide()+'</details>'+(d.missed.length?'<div class="alert">Terlepas sesi? Teruskan pada hari latihan seterusnya. <a href="#adaptations">Lihat pelarasan pelan</a></div>':''));
 if(d.notifications.unread)$('#notification-dot').hidden=false;bindExercises();bindStart();
}
function bindStart(){$$('[data-start]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;const log=await api('/sessions/'+b.dataset.start+'/start','POST',{});go('session/'+log.id);}catch(e){toast(e.message);b.disabled=false;}});}
async function plan(){const [d,{profile:p}]=await Promise.all([api('/plan'),api('/profile')]);if(!d.plan){go('onboarding');return;}const requested=location.hash.split('/')[1];const displayStart=requested&&d.sessions.some(x=>x.scheduled_date===requested)?requested:localToday();const display=d.sessions.filter(x=>x.scheduled_date>=displayStart).slice(0,14);let selected=display.find(x=>x.scheduled_date===requested)||display[0];
 shell(pageHeading('Planner latihan','Pilih hari. Terokai sesi. Fahami pelan kamu.',button('Ubah pilihan '+icon('edit'),'profile','secondary'))+'<section class="planner-intro"><div><span class="eyebrow">PELAN PERIBADI / V'+d.plan.version+'</span><h2>'+esc(splitLabels[d.plan.split_type]||'Latihan peribadi')+'</h2><p>'+esc(d.plan.adjustment_reason)+'</p></div><div class="planner-summary"><strong>'+p.days.length+'<small>hari / minggu</small></strong><strong>'+p.session_minutes+'<small>minit / sesi</small></strong></div></section><section class="card"><div class="card-title"><h2>Pilih hari latihan</h2><span class="small muted">'+(display.length?fmt(display[0].scheduled_date,{day:'numeric',month:'short'})+' – '+fmt(display.at(-1).scheduled_date,{day:'numeric',month:'short'}):'')+'</span></div><div class="planner-calendar">'+display.map(x=>'<button class="calendar-tile '+(x.is_rest?'':'is-training')+'" data-plan-date="'+x.scheduled_date+'" aria-pressed="'+(x===selected)+'"><span>'+fmt(x.scheduled_date,{weekday:'short'})+'</span><strong>'+Number(x.scheduled_date.slice(-2))+'</strong><small>'+ (x.is_rest?'Rehat':x.status==='completed'?'Siap':x.status==='partial'?'Separa':x.status==='missed'?'Terlepas':'Latihan')+'</small></button>').join('')+'</div></section><div id="planned-session" class="card planned-session" aria-live="polite"></div><details class="card guide-disclosure"><summary>Bagaimana pilihan saya menjadi pelan ini?</summary>'+planReason(p,d.plan.split_type)+'<p class="muted">Pelan memilih senaman mengikut pengalaman dan peralatan, mengecualikan tag limitasi, dan mengambil kira pemulihan otot. Prestasi yang direkod membantu pelarasan sesi akan datang.</p><a href="#adaptations">Lihat sejarah pelarasan</a></details>','plan');
 const draw=()=>{$('#planned-session').innerHTML=selected?'<div class="card-title"><div><span class="eyebrow">'+fmt(selected.scheduled_date,{weekday:'long',day:'numeric',month:'long'})+'</span><h2>'+esc(selected.session_label)+'</h2></div>'+icon(selected.is_rest?'leaf':'dumbbell')+'</div>'+(selected.is_rest?'<div class="rest-scene">'+icon('leaf')+'<div><h3>Ruang untuk pulih.</h3><p>Tiada set untuk direkod hari ini. Sesi seterusnya menanti dalam planner.</p></div></div>':exerciseRows(selected.exercises)+(selected.scheduled_date===localToday()&&['scheduled','rescheduled','in_progress'].includes(selected.status)?'<div class="session-footer"><button class="button" data-start="'+selected.id+'">Mula / sambung latihan '+icon('arrow')+'</button></div>':'<p class="muted small">'+(selected.scheduled_date>localToday()?'Sesi boleh dimulakan pada hari yang dijadualkan.':'Rekod sesi tersedia dalam Kemajuan.')+'</p>')):empty('Tiada sesi tersedia','Semak pilihan latihan kamu.');bindExercises();bindStart();};draw();$$('[data-plan-date]').forEach(b=>b.onclick=()=>{selected=display.find(x=>x.scheduled_date===b.dataset.planDate);$$('[data-plan-date]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));draw();});
}
async function logs(){const {logs}=await api('/logs');shell(`${pageHeading('Rekod latihan','Latihan yang disimpan dan sesi yang belum selesai.',button('Kembali ke kemajuan','progress','secondary'))}<div class="card">${logs.length?logs.map(l=>`<a class="exercise-row" href="#${l.ended_at?'log':'session'}/${l.id}"><div class="exercise-art">${icon('log')}</div><div class="exercise-info"><strong>${esc(l.session_label)}</strong><span>${fmt(l.scheduled_date)}</span></div>${badge(l.status)}${icon('chevron')}</a>`).join(''):empty('Log pertama kamu bermula di sini.','Mulakan sesi latihan untuk merekod rep, beban dan usaha.','log')+button('Lihat sesi','dashboard')}</div>`,'logs');}
function setRows(e,locked){return Array.from({length:e.target_sets},(_,i)=>{const s=e.sets.find(s=>s.set_no===i+1);return `<tr data-set="${i+1}"><td>${i+1}</td><td><input aria-label="Rep set ${i+1}" name="reps" type="number" min="1" max="100" step="1" value="${s?.reps||e.target_rep_max}" ${locked?'disabled':''}></td><td><input aria-label="Beban kg set ${i+1}" name="weight_kg" type="number" min="0" max="999" step="0.5" value="${s?.weight_kg??e.target_weight_kg??0}" ${locked?'disabled':''}></td><td><input aria-label="RPE set ${i+1}" name="rpe" type="number" min="1" max="10" step="1" value="${s?.rpe??''}" placeholder="1–10" ${locked?'disabled':''}></td><td><input aria-label="Set ${i+1} selesai" name="done" type="checkbox" ${s?'checked':''} ${locked?'disabled':''}></td></tr>`;}).join('');}
function collectSets(){return $$('[data-set]').filter(tr=>tr.querySelector('[name=done]').checked).map(tr=>({set_no:Number(tr.dataset.set),reps:Number(tr.querySelector('[name=reps]').value),weight_kg:Number(tr.querySelector('[name=weight_kg]').value),rpe:Number(tr.querySelector('[name=rpe]').value)}));}
function startTimer(){clearInterval(state.timer);let remaining=60;const draw=()=>{if($('#rest-time'))$('#rest-time').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;};draw();state.timer=setInterval(()=>{remaining--;draw();if(remaining<=0){clearInterval(state.timer);toast('Masa rehat selesai. Sedia untuk set seterusnya.');}},1000);}
async function workout(id,isLog=false,index=0){let log=await api('/logs/'+id);if(log.ended_at&&!isLog){go('log/'+id);return;}index=Math.min(index,log.exercises.length-1);const e=log.exercises[index];if(!e)throw Error('Tiada senaman dalam sesi.');
 shell(`<div class="workout-stage">${pageHeading(isLog?'Latihan disimpan':esc(log.session_label),fmt(log.scheduled_date),button(icon('back')+' Kembali',isLog?'logs':'dashboard','secondary'))}<div class="card"><div class="row between wrap"><span class="eyebrow">SENAMAN ${index+1} DARIPADA ${log.exercises.length}</span>${workoutStatus(e,log.ended_at)}</div><div class="progress-bar" style="margin-top:17px"><span style="width:${(index+1)/log.exercises.length*100}%"></span></div><div class="workout-intro"><h2>${esc(e.name)}</h2><p class="muted small">${isLog?'Semak set yang telah kamu simpan.':'Ikuti panduan, rekod set, kemudian teruskan ke senaman seterusnya.'}</p></div><div class="field" style="margin-top:22px"><label for="exercise-picker">Navigasi senaman</label><select id="exercise-picker">${log.exercises.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(x.name)} · ${log.ended_at?labels[x.status]:x.sets.length+'/'+x.target_sets+' set'}</option>`).join('')}</select></div>${!isLog?`<div class="workout-visual">${icon('dumbbell')}</div><p class="muted small">${esc(e.instructions)}</p>`:'<div style="height:22px"></div>'}<div class="targets"><div><strong>${e.target_sets}</strong><span>Set sasaran</span></div><div><strong>${e.target_rep_min}–${e.target_rep_max}</strong><span>Ulangan setiap set</span></div><div><strong>${e.target_weight_kg??'Ringan'}${e.target_weight_kg!==null?' kg':''}</strong><span>Beban sasaran</span></div></div><form id="set-form"><div class="form-error"></div><table class="set-table"><thead><tr><th>Set</th><th>Ulangan</th><th>Berat (kg)</th><th>Usaha<br>(1–10)</th><th>Siap</th></tr></thead><tbody>${setRows(e,log.locked)}</tbody></table><p class="muted small">1. Buat ulangan yang disarankan. 2. Isi berat dan usaha (1 = mudah, 10 = paling sukar). 3. Tandakan Siap untuk simpan set. Berat badan sahaja? Isi 0 kg.</p><div class="field"><label for="notes">Nota senaman</label><textarea id="notes" name="notes" maxlength="200" ${log.locked?'disabled':''}>${esc(e.notes)}</textarea><small>Maksimum 200 aksara.</small></div>${log.ended_at?`<p class="small muted">${icon('lock')} ${log.locked?'Log dikunci.':'Boleh diedit sehingga '+fmt(log.edit_locked_at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+'.'}</p>`:`<div class="timer"><span>${icon('clock')} Rehat selepas set</span><strong id="rest-time">01:00</strong><button type="button" id="reset-timer" class="button ghost compact">Mula rehat 60s</button></div>`}<div class="form-actions">${log.locked?'':'<button class="button" type="submit">'+icon('check')+' Simpan perubahan</button>'}${index<log.exercises.length-1?'<button class="button secondary" type="button" id="next-exercise">Senaman seterusnya '+icon('arrow')+'</button>':''}</div></form></div>${!isLog?'<button class="button secondary" style="width:100%;margin-top:20px" id="finish-session">Tamat sesi</button>':''}</div>`,'logs');
 let dirty=false;const save=async()=>{log=await api(`/logs/${id}/exercises/${e.id}`,'PUT',{sets:collectSets(),notes:$('#notes').value});dirty=false;const saved=log.exercises.find(x=>x.id===e.id);if($('#exercise-save-status')&&saved)$('#exercise-save-status').textContent=saved.sets.length+' / '+saved.target_sets+' set disimpan';};
 $('#set-form').addEventListener('input',()=>dirty=true);bindForm('#set-form',async()=>{await save();toast('Log berjaya disimpan.');});
 $('#exercise-picker').onchange=async ev=>{try{if(dirty&&!log.locked)await save();workout(id,isLog,Number(ev.target.value));}catch(err){toast(err.message);ev.target.value=index;}};
 if($('#next-exercise'))$('#next-exercise').onclick=async()=>{try{if(!log.locked)await save();workout(id,isLog,index+1);}catch(err){toast(err.message);}};
 if($('#reset-timer'))$('#reset-timer').onclick=startTimer;
 if(!isLog){$$('[name=done]').forEach(c=>c.onchange=async()=>{try{await save();if(c.checked)startTimer();toast('Set disimpan.');}catch(err){c.checked=!c.checked;toast(err.message);}});$('#finish-session').onclick=()=>confirmAction('Tamatkan sesi?','Set yang belum direkod akan ditanda terlepas. Kamu masih boleh mengedit log selama 24 jam.',async()=>{await save();await api('/sessions/'+id+'/finish','POST',{});go('log/'+id);});}
}
async function progress(){const {exercises}=await api('/exercises');state.exerciseId ||=String(exercises[0]?.id||'');const d=await api(`/progress?exerciseId=${state.exerciseId}&range=${state.range}`);shell(`${pageHeading('Kemajuan kamu','Setiap latihan yang disimpan ialah satu langkah ke hadapan.',`<div class="tabs"><button data-range="week" class="${state.range==='week'?'active':''}">Minggu</button><button data-range="month" class="${state.range==='month'?'active':''}">Bulan</button></div>`)}<div class="row wrap" style="margin-bottom:24px">${button('Lihat semua rekod latihan','logs','secondary')}</div><div class="progress-metrics">${[['Konsistensi',d.consistency+'%','Sesi siap ÷ (siap + terlepas)','chart'],['Latihan berturut-turut',d.streak+' sesi','Sesi dirancang berturut-turut','flame'],['Sesi siap',d.completed,'Dalam julat yang dipilih','check'],['Sesi terlepas',d.missed,'Dalam julat yang dipilih','calendar']].map(([title,n,note,i])=>`<div class="card stat-card"><div class="row between"><small>${title}</small><span class="stat-icon">${icon(i)}</span></div><strong>${n}</strong><p>${note}</p></div>`).join('')}</div><section class="card"><div class="card-title"><h2>Berat yang berjaya diangkat</h2>${icon('chart')}</div><div class="field" style="max-width:300px;margin-bottom:25px"><label for="progress-exercise">Pilih senaman</label><select id="progress-exercise">${exercises.map(e=>`<option value="${e.id}" ${String(e.id)===state.exerciseId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="chart-box"><canvas id="progress-chart" role="img" aria-label="Graf beban tertinggi setiap sesi"></canvas>${!d.points.length?'<div class="chart-empty">Rekod sesi pertama untuk melihat graf kemajuan.</div>':''}</div>${d.points.length?`<details class="small"><summary>Lihat data graf</summary><table class="data"><thead><tr><th>Tarikh</th><th>Beban tertinggi</th></tr></thead><tbody>${d.points.map(p=>`<tr><td>${fmt(p.scheduled_date)}</td><td>${p.top_weight_kg} kg</td></tr>`).join('')}</tbody></table></details>`:''}<p class="muted small" style="margin:18px 0 0">Konsistensi menggunakan sesi selesai dan terlepas, termasuk hari ini. Hari rehat tidak memutuskan rentak latihan.</p></section>`,'progress');
 if(window.Chart){state.chart=new Chart($('#progress-chart'),{type:'line',data:{labels:d.points.map(p=>fmt(p.scheduled_date,{day:'numeric',month:'short'})),datasets:[{label:'Beban (kg)',data:d.points.map(p=>p.top_weight_kg),borderColor:'#ab9bff',backgroundColor:'rgba(168,134,237,0.18)',fill:true,tension:.3,pointRadius:5,pointBackgroundColor:'#ffffff',pointBorderColor:'#a886ed',pointBorderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,grid:{color:'#2a3147'},ticks:{color:'#a9b1c8'},title:{display:true,text:'Beban (kg)',color:'#5141b5'}},x:{grid:{display:false},ticks:{color:'#a99ebc'}}}}});}
 $('#progress-exercise').onchange=e=>{state.exerciseId=e.target.value;progress();};$$('[data-range]').forEach(b=>b.onclick=()=>{state.range=b.dataset.range;progress();});
}
function passwordForm(){return `<h2>Tukar kata laluan</h2><form id="password-form"><div class="form-error"></div><div class="form-grid">${field('Kata laluan lama','old_password','','password','required autocomplete="current-password"')}${field('Kata laluan baharu','new_password','','password','required minlength="8" maxlength="72" autocomplete="new-password"')}${field('Sahkan kata laluan baharu','confirm_password','','password','required minlength="8" autocomplete="new-password"')}</div><div class="form-actions"><button class="button secondary" type="submit">Tukar kata laluan</button></div></form>`;}
function bindPassword(){bindForm('#password-form',async(d,form)=>{const r=await api('/auth/change-password','POST',d);state.csrf=r.csrf;form.reset();toast(r.message);});}
async function profilePage(){const {profile:p}=await api('/profile');const initials=state.user.full_name.split(' ').slice(0,2).map(n=>n[0]).join('');shell(pageHeading('Profil latihan kamu','Satu tempat untuk membentuk rutin, jadual dan pilihan kamu.')+'<div class="profile-studio"><aside class="card profile-passport"><div class="avatar">'+esc(initials)+'</div><span class="eyebrow">FITADAPT MEMBER</span><h2 style="margin-top:14px">'+esc(state.user.full_name)+'</h2><p>'+esc(state.user.email)+'</p><dl class="identity-list">'+[['Matlamat',labels[p.goal]],['Pengalaman',labels[p.level]],['Hari latihan',p.days.length+' / minggu'],['Masa',p.session_minutes+' minit']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'<a href="#logout" class="button ghost">'+icon('logout')+' Log keluar</a></aside><div class="stack"><section class="card"><div class="form-section-title"><span>01 / PILIHAN LATIHAN</span><h2>Rutin yang sesuai dengan kamu</h2></div><form id="profile-form"><div class="form-error"></div><div class="form-grid">'+field('Nama penuh','full_name',state.user.full_name,'text','required maxlength="100"')+field('E-mel','email',state.user.email,'email','disabled')+profileFields(p)+'</div><div class="alert">'+icon('spark')+' Perubahan latihan digunakan mulai esok. Rekod lepas dan sesi hari ini dikekalkan.</div><div class="form-actions"><button class="button" id="profile-submit" type="submit">Simpan perubahan '+icon('check')+'</button></div></form></section><section class="card"><div class="form-section-title"><span>02 / KESELAMATAN AKAUN</span></div>'+passwordForm()+'</section><section class="card"><div class="row between wrap"><div><h3>Jadikan FitAdapt lebih baik.</h3><p class="muted small" style="margin:0">Kongsi pengalaman latihan kamu dengan kami.</p></div>'+button('Beri maklum balas','feedback','secondary')+'</div></section></div></div>','profile');bindDays();bindForm('#profile-form',async(d,form)=>{await api('/profile','PUT',{...parseProfile(d,form),plan_start_date:p.plan_start_date});state.user.full_name=d.full_name;await profilePage();toast('Profil berjaya dikemas kini.');});bindPassword();}
function feedback(){shell(`<div class="narrow">${pageHeading('Suara kamu penting.','Bantu kami membina pengalaman latihan yang lebih baik.')}<section class="card"><form id="feedback-form"><div class="form-error"></div>${[['ease_score','1. Sejauh mana FitAdapt mudah digunakan?','Sangat sukar','Sangat mudah'],['clarity_score','2. Adakah pelan latihan kamu jelas?','Tidak jelas','Sangat jelas'],['adjustment_score','3. Adakah pelarasan automatik membantu?','Tidak membantu','Sangat membantu']].map(([n,q,l,r])=>`<fieldset style="margin-bottom:30px"><legend>${q}</legend><div class="feedback-scale">${[1,2,3,4,5].map(i=>`<label><input type="radio" name="${n}" value="${i}" required><span>${i}</span></label>`).join('')}</div><div class="row between muted" style="font-size:10px"><span>${l}</span><span>${r}</span></div></fieldset>`).join('')}<div class="field"><label for="comments">Apa yang boleh kami perbaiki?</label><textarea id="comments" name="comments" maxlength="2000" placeholder="Kongsikan pengalaman atau cadangan kamu…"></textarea></div><div class="form-actions"><button class="button" type="submit">Hantar maklum balas ${icon('arrow')}</button></div></form></section></div>`,'profile');bindForm('#feedback-form',async d=>{await api('/feedback','POST',{...d,ease_score:Number(d.ease_score),clarity_score:Number(d.clarity_score),adjustment_score:Number(d.adjustment_score)});shell(`<div class="card narrow">${empty('Terima kasih!','Maklum balas kamu membantu kami membina FitAdapt yang lebih baik.','message')}<div style="text-align:center">${button('Kembali ke dashboard','dashboard')}</div></div>`,'profile');});}
async function adaptations(){const {events}=await api('/adaptations');shell(`${pageHeading('Pelan yang berkembang bersama kamu.','Setiap pelarasan ada sebabnya.')}<section class="card">${events.length?events.map(e=>`<div class="list-item"><div class="row between"><span class="badge">${esc(e.rule_code)}</span><small>${fmt(e.created_at)}</small></div><p>${esc(e.reason_text)}</p>${e.new_value!==null?`<small>${esc(e.old_value)} → ${esc(e.new_value)} kg</small>`:''}</div>`).join(''):empty('Pelan kamu baru bermula.','Pelarasan akan muncul selepas kamu merekod latihan atau terlepas sesi.','spark')}</section>`,'plan');}
async function adminDashboard(){const d=await api('/admin/dashboard');const actionLabels={'exercise.save':'Senaman disimpan','exercise.activate':'Senaman diaktifkan','exercise.deactivate':'Senaman dinyahaktifkan','account.suspended':'Akaun digantung','account.active':'Akaun diaktifkan','account.delete':'Akaun dipadam'};shell(`${pageHeading('Gambaran keseluruhan.','Pantau aktiviti dan urus komuniti FitAdapt.')}<div class="grid3">${[['Jumlah pengguna',d.users,d.userChange,'users'],['Senaman aktif',d.exercises,d.exerciseChange,'dumbbell'],['Sesi dilog minggu ini',d.logs,d.logChange,'log']].map(([title,n,change,i])=>`<div class="card stat-card"><div class="row between"><small>${title}</small><span class="stat-icon">${icon(i)}</span></div><strong>${n}</strong><p>${change===null?'Belum ada asas perbandingan':`<span style="color:var(--green)">${change>=0?'+':''}${change}%</span> berbanding minggu lalu`}</p></div>`).join('')}</div><div class="grid2" style="margin-top:25px"><section class="card"><h2>Pautan pantas</h2>${[['admin-exercises','dumbbell','Urus senaman','Tambah dan kemas kini katalog latihan.'],['admin-users','users','Urus akaun','Urus akses dan status pengguna.'],['admin-feedback','message','Maklum balas','Fahami pengalaman pengguna.']].map(([url,i,title,text])=>`<a class="exercise-row" href="#${url}"><div class="exercise-art">${icon(i)}</div><div class="exercise-info"><strong>${title}</strong><span>${text}</span></div>${icon('chevron')}</a>`).join('')}</section><section class="card"><h2>Aktiviti pentadbir</h2>${d.audit.length?d.audit.map(a=>`<div class="list-item"><strong class="small">${esc(actionLabels[a.action]||a.action)}</strong><p class="muted small">${esc(a.full_name||'Akaun dipadam')} · ${fmt(a.created_at)}</p></div>`).join(''):empty('Belum ada aktiviti.','Tindakan pentadbir akan direkodkan di sini.','shield')}</section></div>`,'admin');}
function pagination(d){return `<div class="pagination"><span>${d.total?'Memaparkan '+((d.page-1)*8+1)+'–'+Math.min(d.page*8,d.total)+' daripada '+d.total:'Tiada rekod'}</span><div class="row"><button class="button secondary compact" data-page="${d.page-1}" ${d.page<=1?'disabled':''}>Sebelum</button><span>${d.page} / ${d.pages}</span><button class="button secondary compact" data-page="${d.page+1}" ${d.page>=d.pages?'disabled':''}>Seterusnya</button></div></div>`;}
function filterSelect(name,placeholder,values,value){return `<select class="filter-input" name="${name}" aria-label="${placeholder}"><option value="">${placeholder}</option>${values.map(v=>`<option value="${v}" ${v===value?'selected':''}>${labels[v]||v}</option>`).join('')}</select>`;}
async function adminExercises(query={}){const d=await api('/admin/exercises?'+new URLSearchParams(query));shell(`${pageHeading('Urus senaman.','Katalog latihan untuk setiap tahap dan peralatan.','<button class="button" id="add-exercise">'+icon('plus')+' Tambah senaman</button>')}<section class="card"><form class="filters" id="exercise-filter"><input class="filter-input" name="search" aria-label="Cari senaman" placeholder="Cari nama senaman…" value="${esc(query.search||'')}">${filterSelect('muscle','Semua otot',['chest','back','legs','shoulders','arms','core'],query.muscle)}${filterSelect('equipment','Semua peralatan',['bodyweight','dumbbell','barbell','machine','cable'],query.equipment)}<button class="button secondary" type="submit">Cari</button><button class="button ghost" type="button" id="reset-filter">Reset</button></form><div class="table-wrap"><table class="data"><thead><tr><th>Nama senaman</th><th>Otot sasaran</th><th>Peralatan</th><th>Tahap</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${d.items.map(e=>`<tr><td><strong>${esc(e.name)}</strong><div class="muted">${e.default_sets} set × ${e.default_rep_min}–${e.default_rep_max} rep</div></td><td>${labels[e.muscle_group]}</td><td>${labels[e.equipment_type]}</td><td>${labels[e.level]}</td><td>${badge(e.is_active?'active':'Tidak aktif')}</td><td><div class="row"><button class="button secondary compact" data-edit="${e.id}">Ubah</button><button class="button ghost compact" data-toggle="${e.id}">${e.is_active?'Nyahaktif':'Aktifkan'}</button></div></td></tr>`).join('')}</tbody></table>${!d.total?empty('Tiada senaman ditemui.','Cuba ubah carian atau penapis.','dumbbell'):''}</div>${pagination(d)}</section><div class="alert" style="margin-top:22px">${icon('shield')} Senaman yang digunakan dalam pelan atau log dikekalkan dalam sejarah. Nyahaktifkan untuk mengecualikannya daripada pelan baharu.</div>`,'admin-exercises');
 $('#exercise-filter').onsubmit=e=>{e.preventDefault();adminExercises(formData(e.target));};$('#reset-filter').onclick=()=>adminExercises();$$('[data-page]').forEach(b=>b.onclick=()=>adminExercises({...query,page:b.dataset.page}));$('#add-exercise').onclick=()=>exerciseModal(null,()=>adminExercises(query));$$('[data-edit]').forEach(b=>b.onclick=()=>exerciseModal(d.items.find(e=>e.id===Number(b.dataset.edit)),()=>adminExercises(query)));$$('[data-toggle]').forEach(b=>b.onclick=()=>{const e=d.items.find(e=>e.id===Number(b.dataset.toggle));confirmAction(e.is_active?'Nyahaktifkan senaman?':'Aktifkan senaman?',esc(e.name),async()=>{await api('/admin/exercises/'+e.id+'/active','PATCH',{is_active:!e.is_active});await adminExercises(query);toast('Status senaman dikemas kini.');});});
}
function exerciseModal(existing,refresh){const e=existing||{name:'',muscle_group:'chest',equipment_type:'bodyweight',level:'beginner',split_tag:'push',movement_focus:'none',default_sets:3,default_rep_min:8,default_rep_max:12,load_increment_kg:0,base_load_beginner_kg:0,base_load_intermediate_kg:0,is_active:1,is_compound:1,tags:[],instructions:'',image_url:''};modal(existing?'Ubah senaman':'Tambah senaman',`<form id="exercise-form"><div class="form-error"></div><div class="form-grid">${field('Nama senaman','name',e.name,'text','required maxlength="100"')}${select('Otot sasaran','muscle_group',['chest','back','legs','shoulders','arms','core'],e.muscle_group)}${select('Peralatan','equipment_type',['bodyweight','dumbbell','barbell','machine','cable'],e.equipment_type)}${select('Tahap','level',['beginner','intermediate','advanced'],e.level)}<h3 class="field full" style="margin:10px 0 0">Tetapan latihan</h3>${select('Kategori split','split_tag',['push','pull','legs','core'],e.split_tag)}${select('Fokus pergerakan','movement_focus',['none','squat','hinge'],e.movement_focus)}${field('Set lalai','default_sets',e.default_sets,'number','required min="1" max="6"')}${field('Rep minimum','default_rep_min',e.default_rep_min,'number','required min="1" max="30"')}${field('Rep maksimum','default_rep_max',e.default_rep_max,'number','required min="1" max="50"')}${field('Kenaikan beban (kg)','load_increment_kg',e.load_increment_kg,'number','required min="0" max="20" step="0.5"')}${field('Beban pemula (kg)','base_load_beginner_kg',e.base_load_beginner_kg??'','number','min="0" max="999" step="0.5"')}${field('Beban sederhana (kg)','base_load_intermediate_kg',e.base_load_intermediate_kg??'','number','min="0" max="999" step="0.5"')}<div class="field full"><label for="instructions">Arahan senaman</label><textarea id="instructions" name="instructions" maxlength="3000">${esc(e.instructions)}</textarea></div>${field('URL gambar (HTTPS)','image_url',e.image_url||'','url','maxlength="255"')}<fieldset class="field full"><legend>Tag limitasi</legend><div class="row wrap">${[['knee','Lutut'],['back','Belakang'],['shoulder','Bahu'],['wrist','Pergelangan'],['elbow','Siku'],['neck','Leher']].map(([value,label])=>`<label class="check"><input type="checkbox" name="tags" value="${value}" ${e.tags.includes(value)?'checked':''}>${label}</label>`).join('')}</div></fieldset><label class="check"><input type="checkbox" name="is_compound" ${e.is_compound?'checked':''}>Senaman sendi besar</label><label class="check"><input type="checkbox" name="is_active" ${e.is_active?'checked':''}>Senaman aktif</label></div><div class="form-actions"><button class="button" type="submit">Simpan senaman</button></div></form>`);bindForm('#exercise-form',async(data,form)=>{for(const k of ['default_sets','default_rep_min','default_rep_max','load_increment_kg'])data[k]=Number(data[k]);for(const k of ['base_load_beginner_kg','base_load_intermediate_kg'])data[k]=data[k]===''?null:Number(data[k]);data.tags=[...form.querySelectorAll('[name=tags]:checked')].map(n=>n.value);data.is_compound=Number(!!data.is_compound);data.is_active=Number(!!data.is_active);await api('/admin/exercises'+(existing?'/'+e.id:''),existing?'PUT':'POST',data);$('#modal').close();toast('Senaman disimpan.');await refresh();});}
async function adminUsers(query={}){const d=await api('/admin/users?'+new URLSearchParams(query));shell(`${pageHeading('Urus akaun.','Urus keahlian dan akses dengan selamat.')}<section class="card"><form class="filters" id="users-filter"><input class="filter-input" name="search" aria-label="Cari pengguna" placeholder="Cari nama atau e-mel…" value="${esc(query.search||'')}">${filterSelect('role','Semua peranan',['user','admin','coach'],query.role)}<button class="button secondary" type="submit">Cari</button><button class="button ghost" type="button" id="reset-filter">Reset</button></form><div class="table-wrap"><table class="data"><thead><tr><th>Nama / e-mel</th><th>Peranan</th><th>Status</th><th>Tarikh daftar</th><th>Tindakan</th></tr></thead><tbody>${d.items.map(u=>`<tr><td><strong>${esc(u.full_name)}</strong><div class="muted">${esc(u.email)}</div></td><td>${labels[u.role]}</td><td>${badge(u.status)}</td><td>${fmt(u.created_at,{day:'numeric',month:'short',year:'numeric'})}</td><td>${u.id===state.user.id?'<span class="muted">Akaun anda</span>':`<div class="row"><button class="button secondary compact" data-status="${u.id}">${u.status==='active'?'Gantung':'Aktifkan'}</button><button class="button danger compact" data-delete="${u.id}">Padam</button></div>`}</td></tr>`).join('')}</tbody></table>${!d.total?empty('Tiada akaun ditemui.','Cuba carian lain.','users'):''}</div>${pagination(d)}</section><div class="alert" style="margin-top:22px">${icon('shield')} Pentadbir tidak mempunyai akses kepada log latihan peribadi pengguna.</div>`,'admin-users');$('#users-filter').onsubmit=e=>{e.preventDefault();adminUsers(formData(e.target));};$('#reset-filter').onclick=()=>adminUsers();$$('[data-page]').forEach(b=>b.onclick=()=>adminUsers({...query,page:b.dataset.page}));$$('[data-status]').forEach(b=>b.onclick=()=>{const u=d.items.find(u=>u.id===Number(b.dataset.status));confirmAction(u.status==='active'?'Gantung akaun?':'Aktifkan akaun?',esc(u.full_name)+(u.status==='active'?' akan dilog keluar serta-merta.':''),async()=>{await api('/admin/users/'+u.id+'/status','PATCH',{status:u.status==='active'?'suspended':'active'});await adminUsers(query);});});$$('[data-delete]').forEach(b=>b.onclick=()=>{const u=d.items.find(u=>u.id===Number(b.dataset.delete));confirmAction('Padam akaun secara kekal?',`Akaun ${esc(u.full_name)}, profil, pelan dan lognya akan dipadam. Tindakan ini tidak boleh dibatalkan.`,async()=>{await api('/admin/users/'+u.id,'DELETE',{confirm:true});await adminUsers(query);});});}
async function adminFeedback(page=1){const d=await api('/admin/feedback?page='+page);shell(`${pageHeading('Maklum balas pengguna.','Dengar, fahami, dan tingkatkan pengalaman FitAdapt.','<a class="button secondary" href="/api/admin/feedback/export" download>'+icon('download')+' Eksport CSV</a>')}<div class="grid3" style="margin-bottom:24px">${[['Kemudahan penggunaan','ease'],['Kejelasan pelan','clarity'],['Kegunaan pelarasan','adjustment']].map(([title,key])=>`<div class="card stat-card"><small>${title}</small><strong>${d.averages[key]===null?'—':Number(d.averages[key]).toFixed(1)} <span class="small muted">/ 5</span></strong><p>${d.averages.total} maklum balas</p></div>`).join('')}</div><section class="card"><div class="table-wrap"><table class="data"><thead><tr><th>Pengguna</th><th>Mudah</th><th>Jelas</th><th>Membantu</th><th>Komen</th><th>Tarikh</th></tr></thead><tbody>${d.items.map(f=>`<tr><td>${esc(f.full_name)}</td><td>${f.ease_score}/5</td><td>${f.clarity_score}/5</td><td>${f.adjustment_score}/5</td><td class="comment">${esc(f.comments||'—')}</td><td>${fmt(f.created_at,{day:'numeric',month:'short'})}</td></tr>`).join('')}</tbody></table>${!d.total?empty('Belum ada maklum balas.','Jawapan pengguna akan muncul di sini.','message'):''}</div>${pagination(d)}</section>`,'admin-feedback');$$('[data-page]').forEach(b=>b.onclick=()=>adminFeedback(b.dataset.page));}
function legal(privacy){$('#app').innerHTML=`<header class="public-header">${brand()}${button('Kembali','register','secondary')}</header><main id="main" class="legal card"><h1>${privacy?'Dasar privasi':'Terma penggunaan'}</h1>${privacy?'<p>FitAdapt menyimpan nama, e-mel, profil latihan, limitasi yang anda masukkan, pelan, log set dan maklum balas untuk menyediakan fungsi aplikasi.</p><p>Kata laluan disimpan sebagai hash. Kuki sesi digunakan untuk mengesahkan log masuk. Pentadbir boleh mengurus akaun dan melihat maklum balas, tetapi tidak diberi akses kepada log latihan peribadi melalui aplikasi.</p><p>Data kekal sehingga akaun dipadam oleh pentadbir. Hubungi pentadbir pemasangan FitAdapt anda untuk permintaan akses atau pemadaman. Tiada penjejak pengiklanan digunakan oleh aplikasi ini.</p>':'<p>FitAdapt menyediakan panduan latihan umum berdasarkan maklumat dan rekod yang anda masukkan. Gunakan beban yang sesuai dengan kebolehan anda dan hentikan latihan jika terasa sakit.</p><p>Anda bertanggungjawab menjaga kata laluan dan memberikan maklumat yang tepat. Jangan gunakan aplikasi untuk mengakses akaun orang lain atau mengganggu perkhidmatan.</p><p>Pelarasan automatik ialah cadangan berasaskan peraturan dan tidak menggantikan nasihat jurulatih atau profesional kesihatan. Hubungi pentadbir pemasangan ini untuk bantuan akaun.</p>'}</main>`;}
let renderVersion=0;
async function render(){authModule?.unmountAuth();const version=++renderVersion;state.chart?.destroy();state.chart=null;clearInterval(state.timer);if($('#modal').open)$('#modal').close();if($('#setup-dialog')?.open)$('#setup-dialog').close();const [rawRoute,id]=location.hash.slice(1).split('/');const route=rawRoute||'home';
 try{
  if(['terms','privacy'].includes(route)){legal(route==='privacy');return;}
  if(state.user?.role==='user'&&!state.onboarded&&!['logout','onboarding'].includes(route)){go('onboarding');return;}
  if(route==='home'||route==='how'){landing();if(route==='how')$('#how').scrollIntoView();return;}
  if(route==='login'||route==='register'){await authPage(route==='register');return;}
  if(!state.user){go('login');return;}
  if(route==='logout'){await api('/auth/logout','POST',{});state.user=null;state.csrf='';state.token='';localStorage.removeItem('fitadapt_token');go('login');return;}
  if(state.user.role==='admin'&&!route.startsWith('admin')){go('admin');return;}
  if(state.user.role!=='admin'&&route.startsWith('admin')){go('dashboard');return;}
  if(state.user.role==='user'&&!state.onboarded&&route!=='onboarding'){go('onboarding');return;}
  const routes={dashboard,plan,logs,progress,profile:profilePage,onboarding,feedback,adaptations,admin:adminDashboard,'admin-exercises':adminExercises,'admin-users':adminUsers,'admin-feedback':adminFeedback,'admin-profile':()=>{shell(`<div class="narrow">${pageHeading('Profil pentadbir.',esc(state.user.email))}<section class="card">${passwordForm()}</section></div>`,'admin');bindPassword();}};
  if(route==='session'||route==='log')await workout(id,route==='log');else if(routes[route])await routes[route]();else go(state.user.role==='admin'?'admin':'dashboard');
 }catch(e){if(version!==renderVersion)return;if(e.status===401){state.user=null;go('login');return;}if(state.user)shell(`${pageHeading('Halaman belum dapat dimuatkan.','Sila cuba lagi sebentar.')}<div class="alert error">${esc(e.message)}</div><button class="button" id="retry" style="margin-top:20px">Cuba lagi</button>`);else $('#app').innerHTML=`<main id="main" class="legal"><div class="alert error">${esc(e.message)}</div>${button('Kembali','home')}</main>`;if($('#retry'))$('#retry').onclick=render;}
 window.scrollTo(0,0);
}
window.addEventListener('hashchange',render);
window.addEventListener('unhandledrejection',event=>{toast(event.reason?.message||'Ralat tidak dijangka. Sila cuba lagi.');});
(async()=>{try{const me=await api('/auth/me');if(me.token){state.token=me.token;localStorage.setItem('fitadapt_token',me.token);}Object.assign(state,me);}catch{}await render();})();
